<?php
namespace App\Http\Controllers\Mobile;
use App\Http\Controllers\Controller;use App\Models\Appointment;use App\Services\MobileMutationService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class MobileMutationController extends Controller{public function cancellation(Request $request,Appointment $appointment,MobileMutationService $mutations):JsonResponse{$this->authorize('update',$appointment);$data=$request->validate(['client_request_id'=>['required','uuid'],'reason'=>['nullable','string','max:1000']]);$result=$mutations->run($request->user(),$data['client_request_id'],'appointment.cancellation_request',function()use($appointment,$request,$data){$item=$appointment->cancellationRequest()->firstOrCreate(['patient_id'=>$request->user()->id],['reason'=>$data['reason']??null]);return[['data'=>['id'=>$item->id,'status'=>$item->status],'message'=>'Cancellation request sent.'],201];});return response()->json($result['body'],$result['status'],['X-Idempotent-Replay'=>$result['replayed']?'true':'false']);}}
